* { box-sizing: border-box; }
html, body { margin: 0; width: 100%; height: 100%; overflow: hidden; background: #101114; }
body { color: #f5f2e9; font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; -webkit-tap-highlight-color: transparent; }
#game { position: fixed; inset: 0; overflow: hidden; padding: env(safe-area-inset-top) env(safe-area-inset-right) env(safe-area-inset-bottom) env(safe-area-inset-left); }
canvas { display: block; width: 100%; height: 100%; touch-action: none; user-select: none; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }

(() => {
  'use strict';
  const canvas = document.getElementById('screen');
  const ctx = canvas.getContext('2d');
  const announce = document.getElementById('announcer');
  const cars = [
    { name: 'Kestrel GT', year: 1986, era: '80s · COUPÉ', hp: 148, engine: '2.0L · 16V', color: '#e65f3e', weight: 1040, code: 'KG' },
    { name: 'Raven Turbo', year: 1989, era: '80s · TURBO', hp: 182, engine: '1.8L · TURBO', color: '#4d91c9', weight: 1120, code: 'RT' },
    { name: 'Sakura R', year: 1992, era: '90s · SPORT', hp: 197, engine: '2.0L · VTEC', color: '#d94a59', weight: 1160, code: 'SR' },
    { name: 'Veloce 16V', year: 1995, era: '90s · GT', hp: 150, engine: '2.0L · 16V', color: '#d6a64c', weight: 1090, code: 'V16' },
    { name: 'Apex 2.0', year: 1998, era: '90s · RALLY', hp: 210, engine: '2.0L · AWD', color: '#72a77a', weight: 1280, code: 'A2' },
    { name: 'Monarch V6', year: 2001, era: '00s · SEDÁN', hp: 196, engine: '2.5L · V6', color: '#8a79bd', weight: 1320, code: 'MV' },
    { name: 'Cobalt RS', year: 2004, era: '00s · SPORT', hp: 220, engine: '2.0L · TURBO', color: '#4faaa6', weight: 1240, code: 'CR' },
    { name: 'Nightshift S', year: 2006, era: '00s · CLUB', hp: 245, engine: '2.0L · TURBO', color: '#d47743', weight: 1190, code: 'NS' }
  ];
  let W = 0, H = 0, dpr = 1, hits = [], selected = 2;
  let mode = 'garage', race = null, throttleHeld = false, lastFrame = 0, menuScroll = 0;
  const TAU = Math.PI * 2;
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const rnd = (a, b) => a + Math.random() * (b - a);
  function resize() {
    const r = canvas.getBoundingClientRect(); W = r.width; H = r.height;
    dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = Math.round(W * dpr); canvas.height = Math.round(H * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    draw();
  }
  function roundRect(x, y, w, h, r, fill, stroke, lw = 1) {
    ctx.beginPath(); ctx.roundRect(x, y, w, h, r);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.lineWidth = lw; ctx.strokeStyle = stroke; ctx.stroke(); }
  }
  function text(str, x, y, size, color = '#f7f4ed', weight = 500, align = 'left', font = 'system-ui, sans-serif') {
    ctx.fillStyle = color; ctx.font = `${weight} ${size}px ${font}`; ctx.textAlign = align; ctx.textBaseline = 'middle'; ctx.fillText(str, x, y);
  }
  function line(x1, y1, x2, y2, color, width = 1) {
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.strokeStyle = color; ctx.lineWidth = width; ctx.stroke();
  }
  function addHit(id, x, y, w, h, fn = null) { hits.push({ id, x, y, w, h, fn }); }
  function baseBackground() {
    const g = ctx.createLinearGradient(0, 0, W, H);
    g.addColorStop(0, '#17191e'); g.addColorStop(.52, '#111317'); g.addColorStop(1, '#1a1715');
    ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
    const glow = ctx.createRadialGradient(W * .78, H * .12, 4, W * .78, H * .12, W * .7);
    glow.addColorStop(0, 'rgba(255,117,57,.10)'); glow.addColorStop(1, 'rgba(255,117,57,0)');
    ctx.fillStyle = glow; ctx.fillRect(0, 0, W, H);
    // Sparse workshop-light flecks add depth without competing with the interface.
    ctx.fillStyle = 'rgba(255,255,255,.025)';
    for (let i = 0; i < 50; i++) { const x = (i * 197 + 31) % W, y = (i * 131 + 19) % H; ctx.fillRect(x, y, 1, 1); }
  }
  function drawCar(x, y, scale, car, side = true, glow = false) {
    ctx.save(); ctx.translate(x, y); ctx.scale(scale, scale);
    if (glow) { ctx.shadowColor = car.color; ctx.shadowBlur = 20; }
    // Wheels and compact 80s-to-00s coupe silhouette.
    ctx.fillStyle = '#090a0d';
    for (const wx of [-35, 29]) { roundRect(wx, 11, 20, 12, 4, '#090a0d'); ctx.fillStyle = '#b6b7b4'; ctx.beginPath(); ctx.arc(wx + 10, 17, 3.2, 0, TAU); ctx.fill(); ctx.fillStyle = '#090a0d'; }
    ctx.fillStyle = car.color;
    ctx.beginPath(); ctx.moveTo(-47, 8); ctx.lineTo(-45, -1); ctx.quadraticCurveTo(-40, -7, -25, -8); ctx.lineTo(-12, -18); ctx.quadraticCurveTo(-7, -22, 3, -22); ctx.lineTo(22, -20); ctx.quadraticCurveTo(32, -19, 39, -8); ctx.lineTo(47, -5); ctx.lineTo(49, 6); ctx.quadraticCurveTo(44, 11, 38, 11); ctx.lineTo(-38, 11); ctx.quadraticCurveTo(-44, 11, -47, 8); ctx.fill();
    ctx.fillStyle = '#18252b';
    ctx.beginPath(); ctx.moveTo(-18, -10); ctx.lineTo(-8, -18); ctx.quadraticCurveTo(-4, -20, 2, -19); ctx.lineTo(8, -18); ctx.lineTo(8, -10); ctx.closePath(); ctx.fill();
    ctx.beginPath(); ctx.moveTo(11, -18); ctx.lineTo(22, -17); ctx.quadraticCurveTo(29, -16, 34, -9); ctx.lineTo(11, -9); ctx.closePath(); ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,.2)'; ctx.fillRect(-42, -1, 78, 2);
    if (side) { ctx.fillStyle = '#f4e3b2'; ctx.fillRect(44, -2, 3, 5); ctx.fillStyle = '#ff5143'; ctx.fillRect(-47, -2, 3, 5); }
    else { ctx.fillStyle = '#f4e3b2'; ctx.fillRect(-48, -2, 3, 5); ctx.fillStyle = '#ff5143'; ctx.fillRect(45, -2, 3, 5); }
    ctx.restore();
  }
  function drawGarage() {
    baseBackground(); hits = [];
    const compact = H < 700, phone = W < 600;
    const pad = phone ? 22 : Math.max(34, W * .055);
    text('CUARTO DE MILLA', pad, 30, 11, '#f28a55', 800);
    text('GARAGE  /  01', W - pad, 30, 10, '#75777d', 700, 'right');
    line(pad, 51, W - pad, 51, '#ffffff15');
    text('La calle es tuya.', pad, compact ? 87 : 101, phone ? 30 : 43, '#f7f4ed', 750);
    text('ELIGE TU MÁQUINA', pad, compact ? 119 : 145, 10, '#a7a5a0', 800);
    const gridTop = compact ? 142 : 174;
    const cols = phone ? 2 : 4, gap = phone ? 10 : 14;
    const cardW = (W - pad * 2 - gap * (cols - 1)) / cols;
    let cardH = phone ? (compact ? 100 : 118) : (compact ? 120 : 142);
    if (H < 560) cardH = phone ? 88 : 105;
    const rows = Math.ceil(cars.length / cols);
    const gridHeight = rows * cardH + (rows - 1) * gap;
    const availableBottom = H - (phone ? (compact ? 69 : 78) : 88);
    const maxScroll = Math.max(0, gridTop + gridHeight - availableBottom);
    menuScroll = clamp(menuScroll, 0, maxScroll);
    ctx.save(); ctx.beginPath(); ctx.rect(0, gridTop, W, Math.max(0, availableBottom - gridTop)); ctx.clip();
    cars.forEach((car, i) => {
      const col = i % cols, row = Math.floor(i / cols), x = pad + col * (cardW + gap), y = gridTop + row * (cardH + gap) - menuScroll;
      const active = selected === i;
      roundRect(x, y, cardW, cardH, 12, active ? '#24221e' : '#1a1c20', active ? '#f08c54' : '#ffffff12', active ? 1.5 : 1);
      // Small model stripe and colored miniature.
      roundRect(x + 10, y + 10, 31, 16, 5, `${car.color}28`);
      text(car.era, x + 25, y + 18, 7.5, car.color, 800, 'center');
      text(`${car.year}`, x + cardW - 11, y + 18, 9, '#777a80', 700, 'right');
      const carScale = phone ? .54 : .68;
      drawCar(x + cardW - (phone ? 44 : 55), y + (phone ? 57 : 67), carScale, car);
      text(car.name, x + 11, y + (phone ? 42 : 50), phone ? 13 : 15, '#f1eee8', 720);
      text(car.engine, x + 11, y + (phone ? 61 : 71), 8.5, '#8e9095', 600);
      const base = y + cardH - 17;
      text(`${car.hp}`, x + 11, base, 14, active ? '#ffb17c' : '#e8e4dc', 800);
      text('HP', x + 38, base + 1, 8, '#888a8e', 800);
      text('MÁX. 256 HP', x + cardW - 10, base, 7, '#64666b', 700, 'right');
      addHit(`car-${i}`, x, y, cardW, cardH, () => { selected = i; draw(); });
    });
    ctx.restore();
    const footerY = H - (phone ? (compact ? 58 : 66) : 76);
    const footBg = ctx.createLinearGradient(0, footerY - 15, 0, H); footBg.addColorStop(0, 'rgba(17,19,23,0)'); footBg.addColorStop(.25, '#111317'); footBg.addColorStop(1, '#111317');
    ctx.fillStyle = footBg; ctx.fillRect(0, footerY - 15, W, H - footerY + 15);
    const buttonW = phone ? 153 : 205, buttonH = phone ? 46 : 52;
    const bx = W - pad - buttonW, by = H - buttonH - (phone ? 9 : 12);
    text('402 M  ·  ¼ MILLA', pad, by + buttonH / 2, 9, '#8b8d92', 800);
    roundRect(bx, by, buttonW, buttonH, 8, '#f17b47');
    text('A LA PISTA', bx + buttonW / 2 - 8, by + buttonH / 2, 12, '#171513', 850, 'center');
    text('↗', bx + buttonW - 22, by + buttonH / 2, 17, '#171513', 800, 'center');
    addHit('start', bx, by, buttonW, buttonH, startRace);
    if (maxScroll > 0) text(`${Math.round(menuScroll / maxScroll * 100)}%  ·  DESLIZA`, W / 2, H - 11, 7, '#65676b', 700, 'center');
  }

function startRace() {
  const rivalOptions = cars.map((_, i) => i).filter(i => i !== selected);
  const rivalIndex = rivalOptions.reduce((best, i) => Math.abs(cars[i].hp - cars[selected].hp) < Math.abs(cars[best].hp - cars[selected].hp) ? i : best, rivalOptions[0]);
  race = {
    playerCar: cars[selected], rivalCar: cars[rivalIndex], elapsed: 0, clock: 0, phase: 'countdown',
    distance: 0, rivalDistance: 0, speed: 0, rivalSpeed: 0, rpm: 1100, gear: 1, shifts: 0,
    reaction: null, falseStart: false, lastShift: 0, perfect: false, won: false, rivalGear: 1,
    rivalShiftTimer: 0, finishTime: 0, rivalFinish: 0, message: '',
    trafficSeed: Math.random() * 1000
  };
  mode = 'race'; throttleHeld = false; announce.textContent = `Carrera iniciada. ${race.playerCar.name} contra ${race.rivalCar.name}.`;
  draw();
}
function finishRace(forced = false) {
  if (!race || mode !== 'race') return;
  race.phase = 'finished'; race.won = !forced && race.distance >= 402 && (race.rivalDistance < 402 || race.clock <= race.rivalFinish);
  race.finishTime = race.finishTime || race.clock;
  mode = 'result'; throttleHeld = false;
  announce.textContent = race.falseStart ? 'Salida en falso.' : race.won ? '¡Ganaste la carrera!' : 'Carrera terminada.';
}
const gearLimits = [0, 15, 25, 36, 48, 62];
function shiftPlayer() {
  if (mode !== 'race' || !race || race.phase !== 'running' || race.gear >= 5) return;
  const r = race.rpm;
  race.perfect = r >= 6800 && r <= 7900;
  race.lastShift = race.perfect ? 1.1 : .35;
  race.gear++;
  race.shifts++;
  race.rpm = Math.max(4200, r * .64);
  if (!race.perfect) race.message = r < 6200 ? 'CAMBIO TEMPRANO' : '¡CASI!';
  else race.message = '¡CAMBIO PERFECTO!';
  race.messageUntil = race.clock + .85;
}
function update(dt) {
  if (mode !== 'race' || !race) return;
  race.elapsed += dt;
  if (race.phase === 'countdown') {
    if (race.elapsed >= 3.25) { race.phase = 'running'; race.clock = 0; race.reaction = race.falseStart ? null : race.elapsed - 3.25; }
    return;
  }
  if (race.phase !== 'running') return;
  race.clock += dt;
  if (throttleHeld && race.reaction === null) race.reaction = race.clock;
  const car = race.playerCar;
  const gear = race.gear;
  const limit = gearLimits[gear];
  const throttle = throttleHeld ? 1 : .08;
  const speedRatio = clamp(race.speed / limit, 0, 1.2);
  race.rpm = Math.min(8800, 1050 + speedRatio * 7100);
  const rpmFactor = race.rpm > 8150 ? .12 : race.rpm < 3000 && race.speed > 2 ? .72 : 1;
  const gearFactor = [0, 1, .77, .63, .53, .45][gear];
  const powerFactor = car.hp / 190 * (1120 / car.weight);
  const shiftBoost = race.lastShift > 0 ? (race.perfect ? 1.25 : .88) : 1;
  let accel = throttle * 5.2 * powerFactor * gearFactor * rpmFactor * shiftBoost;
  if (race.speed >= limit && gear < 5) accel *= .035;
  race.speed = clamp(race.speed + (accel - .0025 * race.speed * race.speed) * dt, 0, gear < 5 ? limit * 1.015 : 63);
  race.distance += race.speed * dt;
  race.lastShift = Math.max(0, race.lastShift - dt);
  if (race.messageUntil < race.clock) race.message = '';

  const rivalLimit = gearLimits[race.rivalGear];
  const rivalRatio = clamp(race.rivalSpeed / rivalLimit, 0, 1.2);
  const rivalRpm = 1000 + rivalRatio * 7200;
  if (rivalRpm > 7450 && race.rivalGear < 5) { race.rivalGear++; race.rivalShiftTimer = .18; }
  const aiSkill = (race.rivalCar.hp / 190) * (1120 / race.rivalCar.weight) * 1.01;
  const rivalGearFactor = [0, 1, .77, .63, .53, .45][race.rivalGear];
  let aiAccel = 5.15 * aiSkill * rivalGearFactor * (rivalRpm > 8100 ? .1 : 1) * (race.rivalShiftTimer > 0 ? .86 : 1);
  if (race.rivalSpeed >= rivalLimit && race.rivalGear < 5) aiAccel *= .035;
  race.rivalSpeed = clamp(race.rivalSpeed + (aiAccel - .0025 * race.rivalSpeed * race.rivalSpeed) * dt, 0, race.rivalGear < 5 ? rivalLimit * 1.015 : 63);
  race.rivalDistance += race.rivalSpeed * dt;
  race.rivalShiftTimer = Math.max(0, race.rivalShiftTimer - dt);
  if (race.distance >= 402 && !race.finishTime) race.finishTime = race.clock;
  if (race.rivalDistance >= 402 && !race.rivalFinish) race.rivalFinish = race.clock;
  if (race.finishTime && race.rivalFinish) finishRace();
  else if (race.finishTime && race.clock - race.finishTime > 2.5) finishRace();
}
function drawSpeedRpm(x, y, width) {
  const r = race, color = r.rpm > 7600 ? '#ef684f' : '#f29a61';
  text('VELOCIDAD', x, y, 8, '#868990', 800);
  text(`${Math.round(r.speed * 3.6)}`, x, y + 29, 27, '#f2eee7', 780);
  text('km/h', x + 47, y + 31, 9, '#888a8e', 650);
  const bx = x, by = y + 52, bw = width;
  roundRect(bx, by, bw, 5, 3, '#34363a');
  const fraction = clamp((r.rpm - 1000) / 7600, 0, 1);
  roundRect(bx, by, bw * fraction, 5, 3, color);
  for (let i = 1; i < 8; i++) { ctx.fillStyle = '#17191e'; ctx.fillRect(bx + bw * i / 8 - 1, by, 2, 5); }
  text('RPM', bx, by + 15, 7, '#777a80', 750);
  text(`${Math.floor(r.rpm / 100) / 10}K`, bx + bw, by + 15, 8, color, 800, 'right');
}
function drawRoad() {
  const r = race;
  const top = H * .27, height = H * .47, carX = W * .34;
  // Runoff and subtle trackside gradient.
  const bg = ctx.createLinearGradient(0, top - 35, 0, top + height + 40);
  bg.addColorStop(0, '#202421'); bg.addColorStop(.5, '#2b2d2e'); bg.addColorStop(1, '#1e211f');
  ctx.fillStyle = bg; ctx.fillRect(0, top - 35, W, height + 70);
  ctx.fillStyle = '#16191a'; ctx.fillRect(0, top, W, height);
  ctx.fillStyle = '#2c2e30'; ctx.fillRect(0, top + 8, W, height - 16);
  const laneMid = top + height / 2;
  // White shoulders and center divider.
  line(0, top + 8, W, top + 8, '#eee9d9', 2); line(0, top + height - 8, W, top + height - 8, '#eee9d9', 2);
  ctx.setLineDash([25, 20]); line(0, laneMid, W, laneMid, '#858384', 2); ctx.setLineDash([]);
  // Moving lane ticks and roadside reflectors.
  const ppm = Math.max(W / 166, 2.2);
  const offset = (r.distance * ppm) % 120;
  for (let i = -1; i < W / 120 + 2; i++) {
    const x = i * 120 - offset;
    ctx.fillStyle = '#d7d0bc'; ctx.fillRect(x, laneMid - 2, 54, 4);
    ctx.fillStyle = '#e2a56b'; ctx.fillRect(x + 35, top - 17, 5, 5); ctx.fillRect(x + 35, top + height + 12, 5, 5);
  }
