    for (let yy = 0; yy < stripeH / cell; yy++) for (let xx = 0; xx < 2; xx++) {
      ctx.fillStyle = (xx + yy) % 2 ? '#f5f0e2' : '#17181a'; ctx.fillRect(finishX + xx * stripeW / 2, stripeY + yy * cell, stripeW / 2, cell);
    }
    text('META', finishX + 8, top - 7, 8, '#f3a166', 850, 'center');
  }
  // Lane labels, start-light rig.
  text('LANE 01', 15, top + height * .25, 7, '#898b8e', 800);
  text('LANE 02', 15, top + height * .75, 7, '#898b8e', 800);
  const pY = top + height * .27, aY = top + height * .73;
  const delta = (r.rivalDistance - r.distance) * ppm;
  const aiX = clamp(carX + delta, W * .13, W * .77);
  drawCar(carX, aY, clamp(W / 900, .65, 1.08), r.playerCar, true, true);
  drawCar(aiX, pY, clamp(W / 900, .65, 1.08), r.rivalCar, true, false);
  // Animated wheel streaks while moving.
  if (r.speed > 8) {
    ctx.globalAlpha = .45; ctx.strokeStyle = '#d7d0bc'; ctx.lineWidth = 1;
    for (let i = 0; i < 3; i++) { const y = aY - 5 + i * 8; line(carX - 68 - i * 10, y, carX - 48, y, '#d7d0bc'); }
    ctx.globalAlpha = 1;
  }
  if (r.phase === 'countdown') drawTree(top, height);
  return { top, height, carX };
}
function drawTree(top, roadHeight) {
  const n = Math.min(3, Math.floor(race.elapsed));
  const x = W * .83, y = top + roadHeight / 2 - 34;
  roundRect(x, y, 32, 68, 8, '#151719', '#5a5c5b');
  for (let i = 0; i < 3; i++) {
    const lit = i < n;
    ctx.beginPath(); ctx.arc(x + 16, y + 12 + i * 17, 5, 0, TAU);
    ctx.fillStyle = lit ? '#f0a74a' : '#49372b'; ctx.fill();
    if (lit) { ctx.shadowBlur = 12; ctx.shadowColor = '#f0a74a'; ctx.fill(); ctx.shadowBlur = 0; }
  }
  if (race.elapsed >= 3.25) {
    ctx.beginPath(); ctx.arc(x + 16, y + 62, 6, 0, TAU); ctx.fillStyle = '#47d598'; ctx.fill();
    ctx.shadowBlur = 14; ctx.shadowColor = '#47d598'; ctx.fill(); ctx.shadowBlur = 0;
  }
}

  function drawRace() {
    baseBackground(); hits = [];
    const pad = W < 600 ? 22 : 38;
    text('CUARTO DE MILLA', pad, 27, 10, '#f28a55', 800);
    text('402 M  /  ELIMINACIÓN', W - pad, 27, 9, '#777a80', 750, 'right');
    line(pad, 48, W - pad, 48, '#ffffff15');
    text(race.playerCar.name.toUpperCase(), pad, 68, 11, race.playerCar.color, 850);
    text('VS', W / 2, 68, 9, '#6d7074', 800, 'center');
    text(race.rivalCar.name.toUpperCase(), W - pad, 68, 11, race.rivalCar.color, 850, 'right');
    const road = drawRoad();
    const panelY = road.top + road.height + 28;
    const panelH = H - panelY - 20;
    if (W < 600) {
      const half = (W - pad * 2 - 22) / 2;
      drawSpeedRpm(pad, panelY + 2, half);
      // Distance and gear column.
      text('MARCHA', W - pad - half, panelY + 7, 8, '#868990', 800);
      text(`${race.gear}`, W - pad - half, panelY + 32, 24, '#f3a166', 800);
      text('DISTANCIA', W - pad - half, panelY + 56, 8, '#868990', 800);
      text(`${Math.max(0, Math.round(race.distance))} m`, W - pad - half, panelY + 75, 12, '#f0eee8', 760);
      const barY = panelY + 93;
      roundRect(pad, barY, W - pad * 2, 5, 3, '#34363a'); roundRect(pad, barY, (W - pad * 2) * clamp(race.distance / 402, 0, 1), 5, 3, '#f17b47');
      const btnW = W - pad * 2, btnH = Math.min(64, H * .105), btnY = H - btnH - 12;
      if (mode === 'result') {
        roundRect(pad, btnY, btnW, btnH, 10, race.falseStart ? '#b8443c' : race.won ? '#eb8c52' : '#303237');
        text(race.falseStart ? 'SALIDA EN FALSO · VOLVER AL GARAGE' : race.won ? '¡GANASTE! · TOCA PARA VOLVER' : 'BUENA CARRERA · VOLVER AL GARAGE', W / 2, btnY + btnH / 2, 11, race.won || race.falseStart ? '#171513' : '#f1eee8', 850, 'center');
        addHit('back', pad, btnY, btnW, btnH, () => { mode = 'garage'; race = null; draw(); });
      } else {
        roundRect(pad, btnY, btnW, btnH, 10, throttleHeld ? '#ff9c65' : '#ed7743', throttleHeld ? '#ffc095' : null, 2);
        text(race.phase === 'countdown' ? 'PISA PARA ACELERAR' : 'MANTÉN PARA ACELERAR', W / 2, btnY + btnH / 2 - 5, 12, '#171513', 850, 'center');
        text('SUELTA PARA CAMBIAR · A 7–8K RPM', W / 2, btnY + btnH / 2 + 11, 7, '#4a2418', 800, 'center');
        addHit('throttle', pad, btnY, btnW, btnH);
      }
      if (race.message && mode === 'race') text(race.message, W / 2, btnY - 14, 8, race.perfect ? '#83dfb4' : '#f3a166', 850, 'center');
    } else {
      const col = Math.min(240, W * .25), x = W - pad - col;
      drawSpeedRpm(pad, panelY + 5, col);
      text('MARCHA', x, panelY + 6, 8, '#868990', 800);
      text(`${race.gear}`, x, panelY + 36, 31, '#f3a166', 800);
