function drawRoad(){const r=race,top=H*.27,height=H*.47,carX=W*.34;const bg=ctx.createLinearGradient(0,top-35,0,top+height+40);bg.addColorStop(0,'#202421');bg.addColorStop(.5,'#2b2d2e');bg.addColorStop(1,'#1e211f');ctx.fillStyle=bg;ctx.fillRect(0,top-35,W,height+70);ctx.fillStyle='#16191a';ctx.fillRect(0,top,W,height);ctx.fillStyle='#2c2e30';ctx.fillRect(0,top+8,W,height-16);const mid=top+height/2;line(0,top+8,W,top+8,'#eee9d9',2);line(0,top+height-8,W,top+height-8,'#eee9d9',2);ctx.setLineDash([25,20]);line(0,mid,W,mid,'#858384',2);ctx.setLineDash([]);const ppm=Math.max(W/166,2.2),offset=r.distance*ppm%120;for(let i=-1;i<W/120+2;i++){const x=i*120-offset;ctx.fillStyle='#d7d0bc';ctx.fillRect(x,mid-2,54,4);ctx.fillStyle='#e2a56b';ctx.fillRect(x+35,top-17,5,5);ctx.fillRect(x+35,top+height+12,5,5)}const fx=carX+(402-r.distance)*ppm;if(fx>-20&&fx<W+30){for(let yy=0;yy<(height-16)/12;yy++)for(let xx=0;xx<2;xx++){ctx.fillStyle=(xx+yy)%2?'#f5f0e2':'#17181a';ctx.fillRect(fx+xx*7,top+8+yy*12,7,12)}text('META',fx+8,top-7,8,'#f3a166',850,'center')}text('LANE 01',15,top+height*.25,7,'#898b8e',800);text('LANE 02',15,top+height*.75,7,'#898b8e',800);const py=top+height*.27,ay=top+height*.73,aiX=clamp(carX+(r.rivalDistance-r.distance)*ppm,W*.13,W*.77);drawCar(carX,ay,clamp(W/900,.65,1.08),r.playerCar);drawCar(aiX,py,clamp(W/900,.65,1.08),r.rivalCar);if(r.speed>8){for(let i=0;i<3;i++)line(carX-68-i*10,ay-5+i*8,carX-48,ay-5+i*8,'#d7d0bc')}if(r.phase==='countdown')drawTree(top,height);return{top,height,carX}}

function drawRace(){background();hits=[];const pad=W<600?22:38;text('CUARTO DE MILLA',pad,27,10,'#f28a55',800);text('402 M / ELIMINACIÓN',W-pad,27,9,'#777a80',750,'right');line(pad,48,W-pad,48,'#ffffff15');text(race.playerCar.name.toUpperCase(),pad,68,11,race.playerCar.color,850);text('VS',W/2,68,9,'#6d7074',800,'center');text(race.rivalCar.name.toUpperCase(),W-pad,68,11,race.rivalCar.color,850,'right');const road=drawRoad(),py=road.top+road.height+28,panelH=H-py-20;
if(W<600){const half=(W-pad*2-22)/2;speedPanel(pad,py+2,half);text('MARCHA',W-pad-half,py+7,8,'#868990',800);text(`${race.gear}`,W-pad-half,py+32,24,'#f3a166',800);text('DISTANCIA',W-pad-half,py+56,8,'#868990',800);text(`${Math.max(0,Math.round(race.distance))} m`,W-pad-half,py+75,12,'#f0eee8',760);const by=py+93;roundRect(pad,by,W-pad*2,5,3,'#34363a');roundRect(pad,by,(W-pad*2)*clamp(race.distance/402,0,1),5,3,'#f17b47');const bw=W-pad*2,bh=Math.min(64,H*.105),y=H-bh-12;if(mode==='result'){roundRect(pad,y,bw,bh,10,race.falseStart?'#b8443c':race.won?'#eb8c52':'#303237');text(race.falseStart?'SALIDA EN FALSO · VOLVER AL GARAGE':race.won?'¡GANASTE! · TOCA PARA VOLVER':'BUENA CARRERA · VOLVER AL GARAGE',W/2,y+bh/2,11,race.won||race.falseStart?'#171513':'#f1eee8',850,'center');addHit('back',pad,y,bw,bh,()=>{mode='garage';race=null;draw()})}else{roundRect(pad,y,bw,bh,10,throttleHeld?'#ff9c65':'#ed7743',throttleHeld?'#ffc095':null,2);text(race.phase==='countdown'?'PISA PARA ACELERAR':'MANTÉN PARA ACELERAR',W/2,y+bh/2-5,12,'#171513',850,'center');text('SUELTA PARA CAMBIAR · A 7–8K RPM',W/2,y+bh/2+11,7,'#4a2418',800,'center');addHit('throttle',pad,y,bw,bh)}if(race.message&&mode==='race')text(race.message,W/2,y-14,8,race.perfect?'#83dfb4':'#f3a166',850,'center')}
else{const col=Math.min(240,W*.25),x=W-pad-col;speedPanel(pad,py+5,col);text('MARCHA',x,py+6,8,'#868990',800);text(`${race.gear}`,x,py+36,31,'#f3a166',800);text('DISTANCIA',x+60,py+6,8,'#868990',800);text(`${Math.max(0,Math.round(race.distance))} m`,x+60,py+30,18,'#f0eee8',760);roundRect(x+60,py+48,col-60,5,3,'#34363a');roundRect(x+60,py+48,(col-60)*clamp(race.distance/402,0,1),5,3,'#f17b47');const bw=Math.min(305,W*.36),bh=Math.min(62,panelH*.45),bx=W/2-bw/2,y=H-bh-16;if(mode==='result'){roundRect(bx,y,bw,bh,10,race.falseStart?'#b8443c':race.won?'#eb8c52':'#303237');text(race.falseStart?'SALIDA EN FALSO · GARAGE':race.won?'¡GANASTE! · GARAGE':'CARRERA TERMINADA · GARAGE',W/2,y+bh/2,11,race.won||race.falseStart?'#171513':'#f1eee8',850,'center');addHit('back',bx,y,bw,bh,()=>{mode='garage';race=null;draw()})}else{roundRect(bx,y,bw,bh,10,throttleHeld?'#ff9c65':'#ed7743',throttleHeld?'#ffc095':null,2);text(race.phase==='countdown'?'MANTÉN PARA ACELERAR':'MANTÉN · SUELTA PARA CAMBIAR',W/2,y+bh/2-4,12,'#171513',850,'center');text('SUELTA CERCA DE 7,000 RPM PARA CAMBIO PERFECTO',W/2,y+bh/2+12,8,'#4a2418',800,'center');addHit('throttle',bx,y,bw,bh)}if(race.message&&mode==='race')text(race.message,W/2,y-14,9,race.perfect?'#83dfb4':'#f3a166',850,'center')}
