function draw(){if(!W||!H)return;if(mode==='garage')drawGarage();else drawRace()}
function pointerDown(e){e.preventDefault();canvas.setPointerCapture?.(e.pointerId);const r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top,hit=[...hits].reverse().find(h=>x>=h.x&&x<=h.x+h.w&&y>=h.y&&y<=h.y+h.h);if(hit){if(hit.id==='throttle'&&mode==='race'&&race){if(race.phase==='countdown'&&race.elapsed<3.1){race.falseStart=true;race.message='¡SALIDA EN FALSO!';race.messageUntil=2;finishRace(true)}else if(race.phase==='running'){throttleHeld=true;if(race.reaction===null)race.reaction=race.clock}draw()}else hit.fn?.();return}if(mode==='race'&&race?.phase==='running'){throttleHeld=true;if(race.reaction===null)race.reaction=race.clock}}
function pointerUp(){if(throttleHeld&&mode==='race'&&race?.phase==='running'){throttleHeld=false;shiftPlayer();draw()}}
canvas.addEventListener('pointerdown',pointerDown,{passive:false});window.addEventListener('pointerup',pointerUp,{passive:false});canvas.addEventListener('pointercancel',pointerUp);canvas.addEventListener('wheel',e=>{if(mode==='garage'){menuScroll=Math.max(0,menuScroll+e.deltaY);draw()}},{passive:true});
window.addEventListener('keydown',e=>{if(mode==='garage'&&(e.key==='ArrowDown'||e.key==='ArrowUp')){menuScroll+=e.key==='ArrowDown'?100:-100;draw()}if((e.key===' '||e.key==='ArrowUp')&&mode==='race'&&race?.phase==='running'){e.preventDefault();throttleHeld=true}if((e.key===' '||e.key==='ArrowUp')&&mode==='race'&&race?.phase==='countdown'&&race.elapsed<3.1){race.falseStart=true;finishRace(true);draw()}if(e.key==='Escape'&&mode!=='garage'){mode='garage';race=null;draw()}});window.addEventListener('keyup',e=>{if((e.key===' '||e.key==='ArrowUp')&&throttleHeld){throttleHeld=false;shiftPlayer();draw()}});window.addEventListener('resize',resize);function loop(now){const dt=Math.min(.04,(now-lastFrame)/1000||0);lastFrame=now;if(mode==='race'){update(dt);draw()}requestAnimationFrame(loop)}resize();requestAnimationFrame(loop);
})();

