(()=>{'use strict';
const canvas=document.getElementById('screen'),ctx=canvas.getContext('2d'),announce=document.getElementById('announcer');let W=0,H=0,dpr=1,hits=[],selected=2,mode='garage',race=null,held=false,last=0,scroll=0;
const cars=[['Kestrel GT',1986,'80s · COUPÉ',148,'2.0L · 16V','#e65f3e',1040],['Raven Turbo',1989,'80s · TURBO',182,'1.8L · TURBO','#4d91c9',1120],['Sakura R',1992,'90s · SPORT',197,'2.0L · VTEC','#d94a59',1160],['Veloce 16V',1995,'90s · GT',150,'2.0L · 16V','#d6a64c',1090],['Apex 2.0',1998,'90s · RALLY',210,'2.0L · AWD','#72a77a',1280],['Monarch V6',2001,'00s · SEDÁN',196,'2.5L · V6','#8a79bd',1320],['Cobalt RS',2004,'00s · SPORT',220,'2.0L · TURBO','#4faaa6',1240],['Nightshift S',2006,'00s · CLUB',245,'2.0L · TURBO','#d47743',1190]].map(a=>({name:a[0],year:a[1],era:a[2],hp:a[3],engine:a[4],color:a[5],weight:a[6]}));
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),TAU=Math.PI*2;
function rr(x,y,w,h,r,fill,stroke,lw=1){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.lineWidth=lw;ctx.strokeStyle=stroke;ctx.stroke()}}
function txt(s,x,y,size,color='#f7f4ed',weight=500,align='left'){ctx.fillStyle=color;ctx.font=`${weight} ${size}px system-ui,sans-serif`;ctx.textAlign=align;ctx.textBaseline='middle';ctx.fillText(s,x,y)}
function ln(x,y,a,b,c,w=1){ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(a,b);ctx.strokeStyle=c;ctx.lineWidth=w;ctx.stroke()}
function hit(id,x,y,w,h,fn=null){hits.push({id,x,y,w,h,fn})}
function resize(){const r=canvas.getBoundingClientRect();W=r.width;H=r.height;dpr=Math.min(devicePixelRatio||1,2);canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);draw()}
function bg(){let g=ctx.createLinearGradient(0,0,W,H);g.addColorStop(0,'#17191e');g.addColorStop(.52,'#111317');g.addColorStop(1,'#1a1715');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);g=ctx.createRadialGradient(W*.78,H*.12,4,W*.78,H*.12,W*.7);g.addColorStop(0,'rgba(255,117,57,.10)');g.addColorStop(1,'rgba(255,117,57,0)');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);ctx.fillStyle='rgba(255,255,255,.025)';for(let i=0;i<50;i++)ctx.fillRect((i*197+31)%W,(i*131+19)%H,1,1)}
